from pathlib import Path
import json,subprocess
R=Path.cwd()
policy={'weather_twc':{'evidence_sources':['aviationweather','nws','ecmwf_open','nomads'],'coverage_gaps':['No TWC-specific primary source in registry']},'microstructure':{'evidence_sources':['kalshi_docs','polymarket_docs','cftc'],'coverage_gaps':['No live orderbook snapshot source in hourly registry']},'behavioral':{'evidence_sources':['arxiv'],'discovery_sources':['reddit','youtube'],'coverage_gaps':[]},'informed_flow':{'evidence_sources':['arxiv','cftc'],'discovery_sources':['reddit','youtube'],'coverage_gaps':['No point-in-time participant identity/flow dataset']},'algebra':{'evidence_sources':['kalshi_docs','polymarket_docs'],'discovery_sources':['github'],'coverage_gaps':[]},'settlement':{'evidence_sources':['kalshi_docs','polymarket_docs'],'coverage_gaps':['Venue-specific contract-rule pages may need deeper retrieval than docs landing pages']},'scout':{'evidence_sources':['kalshi_docs','polymarket_docs','cftc','aviationweather','nws','ecmwf_open','nomads','arxiv'],'discovery_sources':['github','reddit','youtube'],'coverage_gaps':[]}}
p=R/'control/hourly/role_source_policy.json';p.write_text(json.dumps(policy,indent=2,sort_keys=True)+chr(10))
r=lambda a:subprocess.run(a,capture_output=True,text=True,check=False)
d=r(['git','diff','--check']);assert d.returncode==0,d.stderr;r(['git','add',str(p)]);c=r(['git','commit','-m','build(research): add role-specific source policy']);ps=r(['git','push','origin','HEAD:main']);print(json.dumps({'ok':True,'roles':len(policy),'twc_gap':policy.get('weather_twc').get('coverage_gaps'),'commit_rc':c.returncode,'push_rc':ps.returncode},indent=2))